    } catch (\Throwable $e) {}
    try {
        $authPurged += (int)$db->exec("DELETE FROM banned_ips WHERE banned_until IS NOT NULL AND banned_until < NOW()");
    } catch (\Throwable $e) {}
    echo "  -> Cleaned {$authPurged} expired security entries.\n";

    // 5. Reconcile missing partner settlements
    echo "[5/5] Running asynchronous partner settlement reconciler...\n";
    $tReconcile = microtime(true);
    if (method_exists('OrdersController', 'healMissingOrderSettlements')) {
        OrdersController::healMissingOrderSettlements($db, true);
    }
    $reconcileDuration = round((microtime(true) - $tReconcile) * 1000, 2);
    echo "  -> Settlement reconciliation completed in {$reconcileDuration} ms.\n";

    $totalDuration = round((microtime(true) - $startTime) * 1000, 2);
    echo "\n====================================================\n";
    echo "Daily Maintenance Completed Successfully in {$totalDuration} ms\n";
    echo "====================================================\n";

    // Log the maintenance run
    SystemLog::write(
        'system',
        'cron_daily_maintenance',
        null,
        'Daily Maintenance',
        json_encode([
            'duration_ms'          => $totalDuration,
            'logs_purged'          => $totalLogsPurged,
            'login_history_purged' => $totalLoginsPurged,
            'notifications_purged' => $totalNotifsPurged,
            'auth_entries_purged'  => $authPurged,
            'reconcile_ms'         => $reconcileDuration
        ]),
        1
    );

    exit(0);
} catch (\Throwable $e) {
    echo "\n[ERROR] Daily Maintenance Failed: " . $e->getMessage() . "\n";
    echo $e->getTraceAsString() . "\n";
